select id, title, pid ,icon,info,url from ums_menu where id in (
    select distinct rm.fk_menu_id
    from ums_emp_role as er join ums_role_menu as rm
         on rm.fk_role_id = er.fk_role_id and er.fk_emp_id=#{param1}
              and er.deleted = 0 and rm.deleted = 0
) and deleted = 0

